function RecordWorkspace({config,storageKey}:{config:ViewConfig;storageKey:string}) {
 const [records,setRecords]=useState(config.seeds); const [query,setQuery]=useState(''); const [status,setStatus]=useState('All statuses'); const [modal,setModal]=useState(false); const [editing,setEditing]=useState<string|null>(null); const [selected,setSelected]=useState<RecordItem|null>(null); const [form,setForm]=useState<Record<string,string>>({}); const [toast,setToast]=useState('');
 useEffect(()=>{try{const raw=localStorage.getItem(storageKey);if(raw)setRecords(JSON.parse(raw) as RecordItem[]);}catch{setRecords(config.seeds);}},[storageKey,config.seeds]);
 useEffect(()=>{try{localStorage.setItem(storageKey,JSON.stringify(records));}catch{/* local persistence optional */}},[records,storageKey]);
 const filtered=useMemo(()=>records.filter(r=>(status==='All statuses'||r.status===status)&&`${r.reference} ${r.title} ${r.party} ${r.description} ${Object.values(r.fields).join(' ')}`.toLowerCase().includes(query.toLowerCase())),[records,query,status]);
 const pending=records.filter(r=>/pending|review|required|queued|awaiting|investigat|draft/i.test(r.status)).length; const total=records.reduce((s,r)=>s+(Number.isFinite(r.amount)?r.amount:0),0);
 const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),2800);}; const openNew=()=>{setEditing(null);setForm({});setModal(true);}; const openEdit=(r:RecordItem)=>{setEditing(r.id);setForm({...r.fields,name:r.title});setSelected(null);setModal(true);};
 const save=(submit:boolean)=>{const missing=config.fields.find(f=>f.required&&!String(form[f.key]??'').trim());if(missing){notify(`${missing.label} is required.`);return;}const old=records.find(r=>r.id===editing);const amount=Number(form.amount||form.total||form.unitPrice||old?.amount||0)||0;const reference=old?.reference??genRef(config.key.toUpperCase().replace(/[^A-Z]/g,'').slice(0,5)||'REC',records.length);const item:RecordItem={id:old?.id??reference,reference,title:form.name||form.item||form.process||form.product||form.source||config.noun,party:form.customer||form.owner||form.cashier||form.associate||form.actor||form.system||'Internal',date:today,amount,status:submit?'Pending Approval':old?.status??'Draft',description:form.notes||form.detail||form.policy||`${config.noun} record`,fields:{...form},history:[...(old?.history??[]),...hist(editing?'Record updated':submit?'Submitted for review':'Draft saved')]};setRecords(prev=>old?prev.map(r=>r.id===old.id?item:r):[item,...prev]);setModal(false);notify(submit?'Submitted for review.':'Saved in this browser.');};
 const advance=(r:RecordItem)=>{const next=config.transitions[r.status];if(!next){notify('No further demo transition is configured.');return;}const updated={...r,status:next,history:[...r.history,...hist(`Status changed to ${next}`)]};setRecords(prev=>prev.map(x=>x.id===r.id?updated:x));setSelected(updated);notify(`Status changed to ${next}.`);};
 return <div className="page-stack phase4-workspace"><div className="demo-banner"><div className="demo-banner-icon"><ShieldCheck size={17}/></div><div><strong>Interactive prototype · browser-local records</strong><span>Forms, lifecycle transitions and history are simulated and saved in this browser. Not connected to a production service.</span></div><span className="demo-pill">DEMO</span></div><div className="finance-metric-grid phase4-metrics"><div className="panel finance-metric"><span>Total records</span><strong>{records.length}</strong><small>In this workspace</small></div><div className="panel finance-metric"><span>Open / review</span><strong>{pending}</strong><small>Awaiting next action</small></div><div className="panel finance-metric"><span>{config.amountLabel??'Indicative value'}</span><strong>{formatCurrency(total)}</strong><small>Illustrative values</small></div><div className="panel finance-metric"><span>Last activity</span><strong>{records[0]?formatDate(records[0].date):'—'}</strong><small>Local record history</small></div></div><section className="panel transactions-panel"><div className="panel-heading phase4-heading"><div><h2>{config.title} register</h2><p>{config.subtitle}</p></div><button className="btn btn-primary" onClick={openNew}><Plus size={15}/> New {config.noun}</button></div><div className="finance-toolbar"><label className="finance-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${config.title.toLowerCase()}...`}/></label><select value={status} onChange={e=>setStatus(e.target.value)}><option>All statuses</option>{Array.from(new Set(records.map(r=>r.status))).map(s=><option key={s}>{s}</option>)}</select></div><div className="table-wrap"><table className="data-table"><thead><tr>{config.columns.map(c=><th key={c.key}>{c.label.toUpperCase()}</th>)}<th>DETAIL</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id} className="clickable-row" onClick={()=>setSelected(r)}>{config.columns.map(c=><td key={c.key}>{c.key==='reference'?<><strong>{r.reference}</strong><small className="finance-subline">{r.title}</small></>:c.key==='title'?<strong>{r.title}</strong>:c.key==='party'?<strong>{r.party}</strong>:c.key==='amount'||c.key==='taxAmount'?formatCurrency(c.key==='taxAmount'?Number(r.fields.taxAmount||0):r.amount):c.key==='status'?<StatusBadge status={r.status}/>:c.key==='date'?formatDate(r.date):(r.fields[c.key]||'—')}</td>)}<td><button className="icon-action" aria-label="Open record details" onClick={e=>{e.stopPropagation();setSelected(r);}}><ArrowRight size={15}/></button></td></tr>)}</tbody></table>{!filtered.length&&<div className="finance-empty"><Search size={24}/><strong>No matching records</strong><span>Change search or create a record.</span></div>}</div><div className="table-bottom"><span>Showing {filtered.length} of {records.length} records</span><span>Persisted locally · no live service</span></div></section>{toast&&<div className="toast-message"><Check size={16}/>{toast}<button onClick={()=>setToast('')} aria-label="Dismiss"><X size={14}/></button></div>}{modal&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setModal(false)}><div className="finance-modal phase4-modal" role="dialog" aria-modal="true"><div className="finance-modal-header"><div><span className="eyebrow">{editing?'EDIT RECORD':'NEW RECORD'}</span><h2>{editing?'Edit':'Create'} {config.noun}</h2><p>Complete the fields and save a draft or submit for review.</p></div><button className="close-button" onClick={()=>setModal(false)} aria-label="Close"><X size={18}/></button></div><div className="finance-form-body"><div className="finance-form-grid">{config.fields.map(f=><label key={f.key} className={f.wide?'wide':''}>{f.label}{f.required?' *':''}{f.type==='textarea'?<textarea rows={3} value={form[f.key]??''} onChange={e=>setForm(v=>({...v,[f.key]:e.target.value}))}/>:f.options?<select value={form[f.key]??''} onChange={e=>setForm(v=>({...v,[f.key]:e.target.value}))}><option value="">Select...</option>{f.options.map(o=><option key={o}>{o}</option>)}</select>:<input type={f.type??'text'} value={form[f.key]??''} onChange={e=>setForm(v=>({...v,[f.key]:e.target.value}))}/>}</label>)}</div><div className="finance-validation-note"><ShieldCheck size={16}/><span>Required-field validation is active. Never enter card numbers, CVV, passwords, private keys or other secrets into this prototype.</span></div></div><div className="finance-modal-footer"><button className="btn btn-secondary" onClick={()=>setModal(false)}>Cancel</button><button className="btn btn-secondary" onClick={()=>save(false)}>Save draft</button><button className="btn btn-primary" onClick={()=>save(true)}><Send size={15}/> Submit</button></div></div></div>}{selected&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setSelected(null)}><div className="finance-modal detail-finance-modal" role="dialog" aria-modal="true"><div className="finance-modal-header"><div><span className="eyebrow">{config.noun.toUpperCase()} · {selected.reference}</span><h2>{selected.title}</h2><p>{selected.description}</p></div><button className="close-button" onClick={()=>setSelected(null)} aria-label="Close"><X size={18}/></button></div><div className="finance-detail-body"><div className="finance-detail-amount"><span>Indicative value</span><strong>{formatCurrency(selected.amount)}</strong><StatusBadge status={selected.status}/></div><div className="finance-detail-grid">{Object.entries(selected.fields).filter(([,v])=>v).map(([k,v])=><div key={k}><span>{k.replace(/([A-Z])/g,' $1').replace(/^./,s=>s.toUpperCase())}</span><strong>{v}</strong></div>)}</div><div className="finance-history"><strong>Activity history</strong>{selected.history.map((h,i)=><div className="finance-history-row" key={`${h.action}-${i}`}><span className="history-dot"/><div><strong>{h.action}</strong><small>{h.by} · {h.at}</small></div></div>)}</div></div><div className="finance-modal-footer"><button className="btn btn-secondary" onClick={()=>setSelected(null)}>Close</button><button className="btn btn-secondary" onClick={()=>openEdit(selected)}>Edit</button>{config.transitions[selected.status]&&<button className="btn btn-primary" onClick={()=>advance(selected)}><BadgeCheck size={15}/> {config.transitions[selected.status]}</button>}</div></div></div>}</div>;
}

export function RetailWorkspace(){const [active,setActive]=useState('pos');const current=retailViews.find(v=>v.key===active)??retailViews[0];return <div className="page-stack"><SectionHeading eyebrow="PHASE 7 · FINAL ERP CAPABILITIES" title="Retail & Edge" subtitle="Unified commerce across assisted checkout, self-service, mobile, offline and hospitality channels." action={<span className="phase-chip">9 capabilities · Demo environment</span>}/><div className="final-capability-grid">{retailViews.map(v=>{const Icon=v.icon;return <button key={v.key} className={`final-capability-card ${active===v.key?'active':''}`} onClick={()=>setActive(v.key)}><Icon size={17}/><strong>{v.label}</strong><span>{v.subtitle}</span></button>;})}</div><RecordWorkspace config={current} storageKey={`radium-final:retail:${current.key}`}/></div>;}

export function PlatformWorkspace({pathname}:{pathname:string}){const [active,setActive]=useState(false);const config=platformConfigs[pathname];if(!config)return <div className="panel">Platform workspace not found.</div>;const Icon=config.icon;return <div className="page-stack"><SectionHeading eyebrow="PHASE 7 · PLATFORM FOUNDATION" title={config.title} subtitle={config.subtitle} action={<span className="phase-chip">{config.capabilities.length} control domains</span>}/><div className="final-capability-grid">{config.capabilities.map((c,i)=><article key={c.title} className="final-capability-card capability-static"><Icon size={17}/><strong>{c.title}</strong><span>{c.description}</span></article>)}</div><RecordWorkspace config={config.view} storageKey={`radium-final:${pathname}:${config.view.key}`}/><div className="finance-control-note"><ShieldCheck size={17}/><span>{config.boundary}</span></div><button className="btn btn-secondary" onClick={()=>setActive(v=>!v)}>{active?'Hide':'Show'} platform foundation checklist</button>{active&&<div className="panel final-checklist">{config.capabilities.map(c=><p key={c.title}><Check size={15}/> <strong>{c.title}</strong> — {c.description}</p>)}</div>}</div>;}

